import numpy as np
from PIL import Image
from match import load, match, peaks

TPL={
 'R1':('drawings/E-201_power_and_device_plan_1.png',1052,1822,34,27),
 'J1':('drawings/E-201_power_and_device_plan_1.png',970,1461,24,24),
 'R5':('drawings/E-201_power_and_device_plan_1.png',515,1790,27,27),
 'R6':('drawings/E-201_power_and_device_plan_1.png',872,1849,27,28),
 'P1':('drawings/E-201_power_and_device_plan_1.png',748,2433,33,30),
 'R4':('drawings/E-202_power_and_device_plan_2.png',1737,569,25,36),
}
def get_templates():
    cache={}
    out={}
    for k,(p,x,y,w,h) in TPL.items():
        if p not in cache: cache[p]=np.array(Image.open(p).convert('L'))
        out[k]=cache[p][y:y+h,x:x+w]
    return out

def scan_sheet(path, thr=0.80):
    img=load(path)
    T=get_templates()
    cands=[]
    for k,t in T.items():
        sc=match(img,t)
        for x,y,s in peaks(sc,thr,12):
            cands.append((k,int(x),int(y),float(s),t.shape[1],t.shape[0]))
    # dedupe: same location within 10px -> keep best score
    cands.sort(key=lambda c:-c[3])
    kept=[]
    for c in cands:
        dup=False
        for k in kept:
            if abs(k[1]-c[1])<12 and abs(k[2]-c[2])<12:
                dup=True; break
        if not dup: kept.append(c)
    return kept

if __name__=='__main__':
    for p in sys.argv[1:]:
        k=scan_sheet(p)
        from collections import Counter
        print('==',p, Counter(c[0] for c in k))
        for c in sorted(k,key=lambda c:(c[2],c[1])):
            print(c[0], c[1]+TPL[c[0]][3]//2, c[2]+TPL[c[0]][4]//2, round(c[3],3))
